(()=>{'use strict';
const $=id=>document.getElementById(id);let client=null,currentUser=null,currentProfile=null,step=0,pendingPlan=null,pendingAvatar=null,lastAuthRun=0;
const interests=new Set(),disciplines=new Set();
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function mount(){document.body.insertAdjacentHTML('beforeend',`
<div id="du-onboarding"><div class="du-onboard-shell"><div class="du-onboard-logo">DrawUp</div><div class="du-progress"><i id="du-progress-bar" style="width:20%"></i></div>
<section class="du-step active"><span class="du-kicker">WELCOME TO DRAWUP</span><h1>Let's draw up your profile.</h1><p>This helps DrawUp personalize your workspace and connect you across DrawUp. You can skip anything and finish it later.</p><div class="du-photo-row"><div class="du-photo-preview" id="du-photo-preview">DU</div><div class="du-photo-upload"><input id="du-photo-input" type="file" accept="image/jpeg,image/png,image/webp"><label for="du-photo-input">Upload profile photo</label><small>JPG, PNG or WebP. DrawUp crops it square.</small></div></div><div class="du-field du-account-email"><label>Signed in as</label><input id="du-account-email" type="email" readonly aria-readonly="true"><small>Your email is private and identifies the DrawUp account you are signed into. Your username is your public DrawUp identity.</small></div><div class="du-two"><div class="du-field"><label>Display name</label><input id="du-name" autocomplete="name"></div><div class="du-field"><label>Username</label><input id="du-username" autocomplete="username" placeholder="yourname"><small id="du-username-status" class="du-username-status">Your username is unique across DrawUp.</small></div></div><div class="du-two"><div class="du-field"><label>Pronouns <span class="du-note">optional</span></label><input id="du-pronouns"></div><div class="du-field"><label>Location <span class="du-note">optional</span></label><input id="du-location" placeholder="City, State / Country"></div></div></section>
<section class="du-step"><span class="du-kicker">YOUR LANE</span><h1>What do you do?</h1><p>Choose everything that fits. This can change as your career changes.</p><div class="du-chips" data-set="disciplines">${['Architecture','Interior Design','Engineering','Construction','Planning','Landscape','Student','Educator','Developer / Owner','Other'].map(x=>`<button class="du-chip" type="button" data-value="${x}">${x}</button>`).join('')}</div><div class="du-field"><label>Title / role <span class="du-note">optional</span></label><input id="du-title" placeholder="Designer, Project Architect, Student…"></div></section>
<section class="du-step"><span class="du-kicker">CURRENT AFFILIATION</span><h1>Where are you connected now?</h1><p>Your current firm does not replace your education or previous work history. This only controls your primary affiliation and coworker view.</p><div class="du-field"><label>Primary affiliation <span class="du-note">optional</span></label><select id="du-aff-type"><option value="">Choose one</option><option value="firm">Firm / company</option><option value="university">University / school</option><option value="organization">Organization</option></select></div><div class="du-field"><label>Name <span class="du-note">optional</span></label><input id="du-aff-name" placeholder="Hampton University, KEi Architects…"></div></section>
<section class="du-step"><span class="du-kicker">EDUCATION + TRADE</span><h1>Add your school or trade history.</h1><p>This belongs to your personal profile even when you currently work at a firm. Add one now and add more later from Profile.</p><div class="du-two"><div class="du-field"><label>School / program <span class="du-note">optional</span></label><input id="du-edu-name" placeholder="University, community college, trade school…"></div><div class="du-field"><label>Type</label><select id="du-edu-type"><option value="university">University / college</option><option value="community_college">Community college</option><option value="trade">Trade / technical school</option><option value="apprenticeship">Apprenticeship</option><option value="other">Other</option></select></div></div><div class="du-two"><div class="du-field"><label>Program / major <span class="du-note">optional</span></label><input id="du-edu-program" placeholder="Architecture, Electrical, Construction…"></div><div class="du-field"><label>Degree / certificate <span class="du-note">optional</span></label><input id="du-edu-degree" placeholder="B.Arch, certificate, apprenticeship…"></div></div><div class="du-two"><div class="du-field"><label>Start year <span class="du-note">optional</span></label><input id="du-edu-start" type="number" min="1900" max="2100"></div><div class="du-field"><label>Graduation / expected year <span class="du-note">optional</span></label><input id="du-edu-grad" type="number" min="1900" max="2100"></div></div></section>
<section class="du-step"><span class="du-kicker">WORK HISTORY</span><h1>Add previous experience.</h1><p>Your current firm and previous firms stay separate. Add one role now or skip and build your full career timeline later.</p><div class="du-two"><div class="du-field"><label>Employer / organization <span class="du-note">optional</span></label><input id="du-work-org" placeholder="Previous firm or employer"></div><div class="du-field"><label>Role <span class="du-note">optional</span></label><input id="du-work-role" placeholder="Designer, intern, project manager…"></div></div><div class="du-two"><div class="du-field"><label>Location <span class="du-note">optional</span></label><input id="du-work-location" placeholder="City, State"></div><div class="du-field"><label>Dates <span class="du-note">optional</span></label><div class="du-two"><input id="du-work-start" type="date"><input id="du-work-end" type="date"></div></div></div></section>
<section class="du-step"><span class="du-kicker">PERSONALIZE DRAWUP</span><h1>What are you here to do?</h1><p>Pick a few. We'll use this to shape your portal—not to limit what you can access.</p><div class="du-chips" data-set="interests">${['Ask Arch Coach','Search projects','Discover firms','Check drawings','Codes + ADA','Details','Learn','Network','Visualize'].map(x=>`<button class="du-chip" type="button" data-value="${x}">${x}</button>`).join('')}</div></section>
<section class="du-step du-ready-step"><div class="du-first-portal"><div class="du-first-grid"></div><div class="du-first-orbit"></div><span class="du-kicker">PROFILE DRAWN UP</span><h1>Your DrawUp is taking shape.</h1><p id="du-ready-intro">Connecting your profile across DrawUp.</p><div class="du-ready-cards"><article><small>YOUR CONNECTION</small><b id="du-ready-aff">DrawUp Community</b><span id="du-ready-aff-sub">Projects · people · resources</span></article><article><small>YOUR PLACE</small><b id="du-ready-place">DrawUp Network</b><span>Firms · projects · AEC community</span></article><article><small>YOUR SCHOOL / TRADE</small><b id="du-ready-school">Your profile</b><span>Education · alumni · organizations</span></article></div><div class="du-ready-status" id="du-onboard-status">READY TO ENTER</div></div></section>
<div class="du-actions"><button class="du-btn ghost" id="du-skip" type="button">Skip for now</button><button class="du-btn primary" id="du-next" type="button">Continue →</button></div></div></div>
<div id="du-login-tunnel"><div class="du-tunnel-grid"></div><div class="du-tunnel-rings"></div><button class="du-skip" id="du-tunnel-skip">Skip →</button><div class="du-tunnel-copy"><div class="du-mark">DU</div><div class="du-tunnel-status" id="du-tunnel-status">IDENTIFYING PLAYER</div><h1 id="du-tunnel-name">Welcome back.</h1><p>Drawing up your workspace…</p></div></div>
<div id="du-portal"><header class="du-portal-top"><button type="button" class="du-portal-brand du-brand-button" data-du-action="public-home">DrawUp <span class="du-kicker">PORTAL</span></button><nav class="du-portal-tabs" id="du-portal-tabs">${['Dashboard','Search','Profile','Projects','Arch Coach','Check','Details','Discover','Connect','Firm','Team','Account'].map((x,i)=>`<button type="button" data-portal-tab="${x.toLowerCase().replace(/ /g,'-')}" class="${i===0?'active':''}">${x}</button>`).join('')}</nav><div class="du-top-user"><span class="du-portal-status" id="du-plan-status"></span><button class="du-avatar" id="du-avatar">DU</button></div><div class="du-profile-panel" id="du-profile-panel"><div style="padding:8px 10px 12px"><b id="du-menu-name">DrawUp Member</b><div class="du-portal-status" id="du-menu-user"></div></div><button data-portal-tab="profile">View / Edit Profile</button><button data-portal-tab="account">Account & Billing</button><button data-du-action="signout">Sign out</button></div></header><main class="du-portal-shell"><aside class="du-side"><div class="du-side-profile"><button class="du-avatar du-avatar-lg" id="du-side-avatar">DU</button><b id="du-side-name">DrawUp Member</b><span id="du-side-role">Member</span></div>${['Dashboard','Search','Profile','Projects','Arch Coach','Check','Details','Discover','Connect','Firm','Team','Account'].map((x,i)=>`<button type="button" data-portal-tab="${x.toLowerCase().replace(/ /g,'-')}" class="${i===0?'active':''}"><span>${['⌂','⌕','◎','▱','✦','✓','⌗','◈','∞','◇','◉','⚙'][i]}</span>${x}</button>`).join('')}<div class="du-side-foot">DrawUp Season 1<br><small>Draw it up. See it through.</small></div></aside><section class="du-workspace"><div id="du-workspace-content"></div></section></main></div></div>`);
 bind();}
function normalizeUsername(v){return (v||'').trim().replace(/^@+/,'').toLowerCase().replace(/[^a-z0-9._]/g,'').slice(0,30)}
let usernameCheckTimer=null;let usernameAvailable=true;
async function checkUsernameAvailability(show=true){const input=$('du-username'),status=$('du-username-status');if(!input||!client||!currentUser)return true;const u=normalizeUsername(input.value);input.value=u;if(u&&normalizeUsername(currentProfile?.username||'')===u){usernameAvailable=true;if(status&&show){status.textContent='✓ @'+u+' is already yours.';status.dataset.state='good'}return true}if(!u){usernameAvailable=true;if(status){status.textContent='Choose a unique DrawUp username.';status.dataset.state='idle'}return true}if(u.length<3){usernameAvailable=false;if(status){status.textContent='Username must be at least 3 characters.';status.dataset.state='bad'}return false}const {data,error}=await client.from('profiles').select('id,username').ilike('username',u).neq('id',currentUser.id).limit(1);if(error){usernameAvailable=false;if(status){status.textContent='Could not verify username yet. Try again.';status.dataset.state='bad'}return false}usernameAvailable=!(data&&data.length);if(status&&show){status.textContent=usernameAvailable?'✓ @'+u+' is available.':'@'+u+' is already taken.';status.dataset.state=usernameAvailable?'good':'bad'}return usernameAvailable}
async function saveCurrentStep(){if(!currentUser||!client)return true;if(step===0){if(!(await checkUsernameAvailability(true)))return false;return await saveProfile({display_name:$('du-name').value.trim()||currentProfile?.display_name||currentUser.email?.split('@')[0],username:normalizeUsername($('du-username').value)||null,pronouns:$('du-pronouns').value.trim()||null,current_location:$('du-location').value.trim()||null,avatar_url:pendingAvatar||currentProfile?.avatar_url||null})}if(step===1)return await saveProfile({title:$('du-title').value.trim()||null,disciplines:[...disciplines]});if(step===2)return await saveProfile({primary_affiliation_type:$('du-aff-type').value||null,primary_affiliation_name:$('du-aff-name').value.trim()||null});return true}
function showStep(n){const total=document.querySelectorAll('.du-step').length;step=Math.max(0,Math.min(total-1,n));document.querySelectorAll('.du-step').forEach((x,i)=>x.classList.toggle('active',i===step));$('du-progress-bar').style.width=(((step+1)/total)*100)+'%';$('du-next').textContent=step===total-1?'Enter DrawUp →':'Continue →';$('du-skip').style.visibility=step===total-1?'hidden':'visible';if(step===total-1)readyPreview();}
function bind(){$('du-photo-input').addEventListener('change',handlePhoto);document.addEventListener('click',e=>{const t=e.target.closest('[data-portal-tab]');if(t){e.preventDefault();openPortalTab(t.dataset.portalTab);}});document.querySelectorAll('.du-chip').forEach(b=>b.addEventListener('click',()=>{b.classList.toggle('on');const set=b.closest('[data-set]').dataset.set==='interests'?interests:disciplines;b.classList.contains('on')?set.add(b.dataset.value):set.delete(b.dataset.value)}));$('du-next').onclick=async()=>{if(step===document.querySelectorAll('.du-step').length-1){await finishOnboarding();return}if(await saveCurrentStep())showStep(step+1)};$('du-skip').onclick=async()=>{await saveCurrentStep();showStep(step+1)};$('du-username').addEventListener('input',()=>{usernameAvailable=false;const st=$('du-username-status');if(st){st.textContent='Checking username…';st.dataset.state='idle'}clearTimeout(usernameCheckTimer);usernameCheckTimer=setTimeout(()=>checkUsernameAvailability(true),120)});$('du-username').addEventListener('blur',()=>checkUsernameAvailability(true));$('du-tunnel-skip').onclick=openPortal;$('du-avatar').onclick=()=>$('du-profile-panel').classList.toggle('open');$('du-exit-portal').onclick=closePortal;document.addEventListener('click',e=>{const p=e.target.closest('[data-du-page]');if(p){closePortal();navigate(p.dataset.duPage)}const a=e.target.closest('[data-du-action]');if(a){if(a.dataset.duAction==='signout')signOut();if(a.dataset.duAction==='public-home'){openPortalTab('dashboard')}if(a.dataset.duAction==='profile')openProfileEditor();if(a.dataset.duAction==='billing'){closePortal();navigate('pricing')}}});}
async function handlePhoto(e){const file=e.target.files&&e.target.files[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){alert('Choose a JPG, PNG or WebP image.');e.target.value='';return;}if(file.size>8*1024*1024){alert('Choose an image under 8 MB.');e.target.value='';return;}const img=new Image();const url=URL.createObjectURL(file);await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const size=384,canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');const scale=Math.max(size/img.naturalWidth,size/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);URL.revokeObjectURL(url);pendingAvatar=canvas.toDataURL('image/jpeg',.82);renderAvatarPreview(pendingAvatar);}
function renderAvatarPreview(src){const box=$('du-photo-preview');if(!box)return;if(src)box.innerHTML='<img alt="Profile photo" src="'+src+'">';else box.textContent=((currentProfile?.display_name||currentUser?.email||'DU').match(/\b\w/g)||['D','U']).slice(0,2).join('').toUpperCase();}
async function waitClient(){for(let i=0;i<50;i++){if(window.drawupSupabaseClient)return window.drawupSupabaseClient;await new Promise(r=>setTimeout(r,100))}return null;}
async function loadProfile(user){if(!client)return null;const {data,error}=await client.from('profiles').select('*').eq('id',user.id).maybeSingle();if(error){console.warn('DrawUp profile:',error.message);return null}return data;}
async function saveProfile(fields){if(!client||!currentUser)return false;const {error}=await client.from('profiles').update(fields).eq('id',currentUser.id);if(error){$('du-onboard-status')&&($('du-onboard-status').textContent=error.message);return false}currentProfile={...(currentProfile||{}),...fields};return true;}
function readyPreview(){const aff=$('du-aff-name').value.trim(),place=$('du-location').value.trim(),school=$('du-edu-name').value.trim();$('du-ready-aff').textContent=aff||'DrawUp Community';$('du-ready-place').textContent=place||'DrawUp';$('du-ready-school').textContent=school||'Your profile';$('du-ready-aff-sub').textContent=aff?'Team · projects · resources':'Projects · people · resources';$('du-ready-intro').textContent=[school,place].filter(Boolean).length?'Connecting '+[school,place].filter(Boolean).join(' · ')+' to your Portal.':'Connecting your profile across DrawUp.';}
function withTimeout(p,ms){return Promise.race([p,new Promise((_,rej)=>setTimeout(()=>rej(new Error('timeout')),ms))])}
async function finishOnboarding(){if(!(await checkUsernameAvailability(true)))return;readyPreview();const status=$('du-onboard-status'),next=$('du-next');next.disabled=true;const fields={display_name:$('du-name').value.trim()||currentProfile?.display_name||currentUser?.email?.split('@')[0],username:normalizeUsername($('du-username').value)||null,pronouns:$('du-pronouns').value.trim()||null,current_location:$('du-location').value.trim()||null,title:$('du-title').value.trim()||null,disciplines:[...disciplines],primary_affiliation_type:$('du-aff-type').value||null,primary_affiliation_name:$('du-aff-name').value.trim()||null,onboarding_completed_at:new Date().toISOString(),onboarding_interests:[...interests],avatar_url:pendingAvatar||currentProfile?.avatar_url||null};status.textContent='SAVING PROFILE';let critical=false;try{critical=await withTimeout(saveProfile(fields),3000)}catch(e){console.warn('Profile save timeout/error:',e.message)}if(!critical){status.textContent='ENTERING DRAWUP — PROFILE DETAILS CAN BE FINISHED INSIDE';currentProfile={...(currentProfile||{}),...fields};setTimeout(()=>{$('du-onboarding').classList.remove('open');openPortal();openPortalTab('profile')},350);return}status.textContent='CONNECTING YOUR WORLD';const jobs=[];const edu=$('du-edu-name').value.trim();if(edu){const payload={user_id:currentUser.id,institution_name:edu,institution_type:$('du-edu-type').value||'other',program:$('du-edu-program').value.trim()||null,degree_or_certificate:$('du-edu-degree').value.trim()||null,start_year:Number($('du-edu-start').value)||null,graduation_year:Number($('du-edu-grad').value)||null,status:(Number($('du-edu-grad').value)&&Number($('du-edu-grad').value)<new Date().getFullYear())?'alumni':'student',is_primary:fields.primary_affiliation_type==='university'&&!!fields.primary_affiliation_name&&fields.primary_affiliation_name.toLowerCase()===edu.toLowerCase(),discoverable:true};jobs.push(client.from('profile_education').insert(payload))}const org=$('du-work-org').value.trim(),role=$('du-work-role').value.trim();if(org&&role)jobs.push(client.from('career_timeline').insert({user_id:currentUser.id,role,organization:org,location:$('du-work-location').value.trim()||null,start_date:$('du-work-start').value||null,end_date:$('du-work-end').value||null}));Promise.allSettled(jobs).then(r=>r.forEach(x=>{if(x.status==='rejected')console.warn('Secondary profile save:',x.reason)}));currentProfile={...(currentProfile||{}),...fields};status.textContent='DRAWING UP YOUR PORTAL';setTimeout(()=>{status.textContent="LET'S PLAY"},650);setTimeout(()=>{$('du-onboarding').classList.remove('open');openPortal();openPortalTab('profile')},1300);}
function prefill(){if($('du-account-email'))$('du-account-email').value=currentUser?.email||'';if(!currentProfile)return;pendingAvatar=currentProfile.avatar_url||null;renderAvatarPreview(pendingAvatar);$('du-name').value=currentProfile.display_name||'';$('du-username').value=currentProfile.username||'';$('du-pronouns').value=currentProfile.pronouns||'';$('du-location').value=currentProfile.current_location||'';$('du-title').value=currentProfile.title||'';$('du-aff-type').value=currentProfile.primary_affiliation_type||'';$('du-aff-name').value=currentProfile.primary_affiliation_name||'';(currentProfile.disciplines||[]).forEach(x=>disciplines.add(x));document.querySelectorAll('[data-set="disciplines"] .du-chip').forEach(b=>b.classList.toggle('on',disciplines.has(b.dataset.value)));}
function onboarding(forceEdit=false){if(currentProfile?.onboarding_completed_at&&!forceEdit){openPortal();return}prefill();showStep(0);$('du-onboarding').classList.add('open');}
function tunnel(){const name=currentProfile?.display_name||currentUser?.email?.split('@')[0]||'Player';$('du-tunnel-name').textContent='Welcome back, '+name+'.';$('du-login-tunnel').classList.add('open');const s=['IDENTIFYING PLAYER','LOADING PROFILE','CONNECTING PROJECTS','LOADING DRAWUP',"LET'S PLAY."];let i=0;$('du-tunnel-status').textContent=s[0];const timer=setInterval(()=>{i++;if(i<s.length)$('du-tunnel-status').textContent=s[i];if(i===s.length-1){clearInterval(timer);setTimeout(openPortal,500)}},420);}
function avatarHTML(){const src=currentProfile?.avatar_url;const n=currentProfile?.display_name||currentUser?.email?.split('@')[0]||'DU';return src?`<img src="${esc(src)}" alt="${esc(n)}">`:esc(n.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase());}
function syncPortalIdentity(){const n=currentProfile?.display_name||currentUser?.email?.split('@')[0]||'DrawUp Member';$('du-menu-name').textContent=n;$('du-menu-user').textContent=currentProfile?.username?'@'+currentProfile.username:(currentUser?.email||'');$('du-side-name').textContent=n;$('du-side-role').textContent=currentProfile?.title||currentProfile?.primary_affiliation_name||'DrawUp Member';['du-avatar','du-side-avatar'].forEach(id=>{const a=$(id);if(!a)return;if(currentProfile?.avatar_url){a.classList.add('has-photo');a.style.backgroundImage=`url(${currentProfile.avatar_url})`;a.textContent='';}else{a.classList.remove('has-photo');a.style.backgroundImage='';a.textContent=n.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}});}
function statCard(label,value,sub=''){return `<article class="du-stat"><span>${label}</span><strong>${value}</strong>${sub?`<small>${sub}</small>`:''}</article>`}
async function openPortalTab(tab='dashboard'){document.querySelectorAll('[data-portal-tab]').forEach(x=>x.classList.toggle('active',x.dataset.portalTab===tab));const w=$('du-workspace-content');if(!w)return;w.innerHTML='<div class="du-loading">DRAWING IT UP…</div>';if(tab==='dashboard')return renderDashboard(w);if(tab==='search')return renderPortalSearch(w);if(tab==='profile')return renderProfile(w);if(tab==='firm')return renderFirm(w);if(tab==='team')return renderTeam(w);if(tab==='account')return renderAccount(w);if(tab==='projects')return renderSimple(w,'Projects','Your DrawUp projects, recent work and saved project activity will live here.','Start or open a project from this workspace without leaving the Portal.');if(tab==='arch-coach')return renderSimple(w,'Arch Coach','Your AEC copilot inside the Portal.','Ask questions, continue threads, research codes and work with project context.');if(tab==='check')return renderSimple(w,'Check','Code, ADA, life-safety and drawing review.','Checks stay connected to your account and projects.');if(tab==='details')return renderSimple(w,'Details','Your personal and firm detail library.','Saved details, requested files and project-stage downloads appear here.');if(tab==='discover')return renderSimple(w,'Discover','Projects, firms, people, universities and resources.','Search the DrawUp knowledge graph without leaving your workspace.');if(tab==='connect')return renderSimple(w,'Connect','Your AEC network.','Connections, messages, schools, organizations and coworkers live here.');}
function renderPortalSearch(w){w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">DRAWUP SEARCH</span><h1>What are you drawing up?</h1><p>Search projects, firms, people, universities, codes, details and resources.</p></div></div><div class="du-search-stage"><div class="du-search-holo"><div class="du-holo-model"><i></i><i></i><i></i><b>DU</b></div></div><form id="du-portal-search-form" class="du-search-box"><input id="du-portal-search-input" type="search" placeholder="Search projects, firms, universities, people, codes, details…" autocomplete="off"><button class="du-btn primary" type="submit">Search DrawUp →</button></form><div class="du-search-types">${['Projects','Firms','People','Universities','Codes','Details','Resources'].map(x=>`<button type="button" data-search-type="${x}">${x}</button>`).join('')}</div><p class="du-muted">Search uses the same DrawUp discovery experience as the public site while keeping you signed into your Portal.</p></div>`;const f=$('du-portal-search-form'),q=$('du-portal-search-input');f.onsubmit=e=>{e.preventDefault();const term=(q.value||'').trim();if(!term)return;closePortal();const searchInput=document.querySelector('input[type="search"], #search-input, [data-search-input]');if(searchInput){searchInput.value=term;searchInput.dispatchEvent(new Event('input',{bubbles:true}));searchInput.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));}else{location.hash='#search';setTimeout(()=>{const i=document.querySelector('input[type="search"], #search-input, [data-search-input]');if(i){i.value=term;i.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}))}},150)}};w.querySelectorAll('[data-search-type]').forEach(b=>b.onclick=()=>{q.value=b.dataset.searchType+' ';q.focus()})}
async function renderDashboard(w){let credits=null;try{const {data}=await client.from('arch_coach_credit_accounts').select('*').eq('user_id',currentUser.id).maybeSingle();credits=data}catch(e){}const unlimited=!!credits?.unlimited_access;const remaining=(credits?.monthly_credits_remaining||0)+(credits?.purchased_credits_remaining||0);const n=currentProfile?.display_name||'there';w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">YOUR DRAWUP</span><h1>Welcome, ${esc(n)}.</h1><p>${esc(currentProfile?.primary_affiliation_name||'Your AEC workspace is ready.')}</p></div><div class="du-live-pill">● PORTAL LIVE</div></div><div class="du-stats">${statCard('Arch Coach',unlimited?'Unlimited':remaining+' credits',unlimited?'Personal unlimited access':'Available balance')}${statCard('Plan',esc(credits?.plan_code||'Explore'),'Current account')}${statCard('Profile',currentProfile?.profile_verified?'Verified':'Active',esc(currentProfile?.username?'@'+currentProfile.username:'Complete your username'))}${statCard('Affiliation',esc(currentProfile?.primary_affiliation_name||'Not set'),currentProfile?.affiliation_verified?'Verified':'Personal profile')}</div><div class="du-portal-holo"><div class="du-holo-copy"><span class="du-kicker">DRAWUP COMMAND CENTER</span><h2>What are you drawing up?</h2><p>Projects · firms · universities · people · codes · details · resources</p><button class="du-btn primary" data-portal-tab="search">Search DrawUp →</button></div></div><div class="du-dash-grid"><article class="du-glass du-command"><span class="du-kicker">COMMAND CENTER</span><h2>What are you drawing up?</h2><div class="du-quick">${[['✦','Ask Arch Coach','arch-coach'],['▱','Projects','projects'],['✓','Run a Check','check'],['⌕','Discover','discover']].map(x=>`<button data-portal-tab="${x[2]}"><b>${x[0]}</b><span>${x[1]}</span></button>`).join('')}</div></article><article class="du-glass du-usage"><span class="du-kicker">USAGE</span><h2>${unlimited?'Unlimited':'Arch Coach Credits'}</h2><div class="du-orbit"><i></i><b>${unlimited?'∞':remaining}</b></div><p>${unlimited?'No DrawUp credit limit on this personal account.':'Monthly + purchased credits currently available.'}</p><button data-portal-tab="account">View account usage →</button></article><article class="du-glass"><span class="du-kicker">PROFILE</span><h2>${esc(currentProfile?.display_name||'Your profile')}</h2><p>${esc([currentProfile?.title,currentProfile?.primary_affiliation_name].filter(Boolean).join(' · ')||'Build your AEC identity.')}</p><button data-portal-tab="profile">Open profile →</button></article><article class="du-glass"><span class="du-kicker">TEAM</span><h2>Your coworkers on DrawUp</h2><p>See DrawUp members connected to ${esc(currentProfile?.primary_affiliation_name||'your firm')}.</p><button data-portal-tab="team">View team →</button></article></div>`;}
async function renderProfile(w){const n=currentProfile?.display_name||'DrawUp Member';let edu=[],career=[];try{const [e,c]=await Promise.all([client.from('profile_education').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}),client.from('career_timeline').select('*').eq('user_id',currentUser.id).order('start_date',{ascending:false})]);edu=e.data||[];career=c.data||[]}catch(e){}w.innerHTML=`<div class="du-profile-cover"><div class="du-profile-orb">${avatarHTML()}</div><div><span class="du-kicker">DRAWUP PROFILE</span><h1>${esc(n)}</h1><p>${esc([currentProfile?.title,currentProfile?.primary_affiliation_name,currentProfile?.current_location].filter(Boolean).join(' · '))}</p><div class="du-badges">${(currentProfile?.disciplines||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><button class="du-btn primary" id="du-edit-profile">Edit profile</button></div><div class="du-subtabs"><button class="active">Overview</button><button>Projects</button><button>Experience</button><button>Education + Trade</button><button>Credentials</button><button>Connections</button><button>Saved</button></div><div class="du-profile-grid"><article class="du-glass"><span class="du-kicker">CURRENT AFFILIATION</span><h2>${esc(currentProfile?.primary_affiliation_name||'Add your firm, school or organization')}</h2><p>Your current affiliation stays separate from your personal history.</p></article><article class="du-glass"><span class="du-kicker">WORK EXPERIENCE</span><h2>${career.length} role${career.length===1?'':'s'}</h2>${career.slice(0,4).map(x=>`<p><b>${esc(x.role)}</b>${x.organization?' · '+esc(x.organization):''}</p>`).join('')||'<p>Add current and previous firms, employers and roles.</p>'}</article><article class="du-glass"><span class="du-kicker">EDUCATION + TRADE</span><h2>${edu.length} record${edu.length===1?'':'s'}</h2>${edu.slice(0,4).map(x=>`<p><b>${esc(x.institution_name)}</b>${x.program?' · '+esc(x.program):''}</p>`).join('')||'<p>Add universities, colleges, trade schools, technical programs and apprenticeships.</p>'}</article><article class="du-glass"><span class="du-kicker">ABOUT</span><p>${esc(currentProfile?.bio||'Add a bio to tell the DrawUp community about your work and interests.')}</p></article></div>`;$('du-edit-profile').onclick=openProfileEditor;}
async function firmMembers(){const firm=currentProfile?.primary_affiliation_name;if(!firm||!client)return[];const {data}=await client.from('profiles').select('id,display_name,username,title,avatar_url,disciplines,profile_verified,primary_affiliation_name').eq('primary_affiliation_name',firm).eq('discoverable',true).limit(100);return data||[];}
async function renderFirm(w){const firm=currentProfile?.primary_affiliation_name;if(!firm){w.innerHTML=`<div class="du-empty"><span class="du-kicker">FIRM</span><h1>Add your firm to unlock your firm page.</h1><p>Personal accounts can still have a firm page. Add a primary firm affiliation from Profile; a firm subscription is not required.</p><button class="du-btn primary" data-portal-tab="profile">Update profile</button></div>`;return;}const members=await firmMembers();w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">YOUR FIRM</span><h1>${esc(firm)}</h1><p>Your personal DrawUp account is connected to this firm workspace.</p></div><span class="du-live-pill">${members.length} DRAWUP MEMBER${members.length===1?'':'S'}</span></div><div class="du-subtabs"><button class="active">Overview</button><button data-portal-tab="team">Team</button><button>Projects</button><button>Pursuits</button><button>Firm Library</button><button>Usage</button></div><div class="du-dash-grid"><article class="du-glass du-command"><span class="du-kicker">FIRM PAGE</span><h2>${esc(firm)}</h2><p>Firm identity, projects, people and shared DrawUp activity live here. Your personal account can view this even without a firm subscription.</p></article><article class="du-glass"><span class="du-kicker">TEAM</span><h2>${members.length} coworkers on DrawUp</h2><p>Discover coworkers who list this firm as their affiliation.</p><button data-portal-tab="team">Open team →</button></article></div>`;}
async function renderTeam(w){const firm=currentProfile?.primary_affiliation_name;if(!firm){w.innerHTML='<div class="du-empty"><h1>Team</h1><p>Add your firm affiliation to see coworkers on DrawUp.</p><button class="du-btn primary" data-portal-tab="profile">Update profile</button></div>';return;}const members=await firmMembers();w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">TEAM</span><h1>${esc(firm)}</h1><p>Coworkers on DrawUp. This is available from personal accounts too.</p></div></div><div class="du-team-grid">${members.length?members.map(m=>`<article class="du-person"><div class="du-person-avatar">${m.avatar_url?`<img src="${esc(m.avatar_url)}">`:esc((m.display_name||'DU').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase())}</div><div><h3>${esc(m.display_name||'DrawUp Member')}</h3><p>${esc(m.title||'AEC Professional')}</p><small>${m.profile_verified?'✓ Verified profile':esc(m.username?'@'+m.username:'DrawUp member')}</small></div></article>`).join(''):'<div class="du-empty"><h2>No coworkers found yet.</h2><p>When coworkers join DrawUp and add this firm, they will appear here.</p></div>'}</div>`;}
async function renderAccount(w){let c=null;try{const {data}=await client.from('arch_coach_credit_accounts').select('*').eq('user_id',currentUser.id).maybeSingle();c=data}catch(e){}const unlimited=!!c?.unlimited_access;w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">ACCOUNT</span><h1>Plan & usage</h1><p>Billing, credits and account preferences.</p></div></div><div class="du-stats">${statCard('Plan',esc(c?.plan_code||'Explore'),'Current plan')}${statCard('Monthly credits',unlimited?'Unlimited':String(c?.monthly_credits_remaining||0),'Remaining')}${statCard('Purchased credits',unlimited?'Unlimited':String(c?.purchased_credits_remaining||0),'Remaining')}${statCard('Access',unlimited?'Unlimited':'Metered','Arch Coach')}</div><article class="du-glass"><h2>Account</h2><p>${esc(currentUser?.email||'')}</p><button class="du-btn ghost" data-du-action="signout">Sign out</button></article>`;}
function renderSimple(w,title,desc,sub){w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">DRAWUP PORTAL</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div></div><article class="du-glass du-feature-stage"><div class="du-stage-orb"><i></i><b>DU</b></div><h2>${esc(title)} lives inside your Portal.</h2><p>${esc(sub)}</p><p class="du-muted">This workspace is now contained inside the signed-in DrawUp shell rather than sending you back to the public site.</p></article>`;}
function openPortal(){$('du-login-tunnel').classList.remove('open');$('du-onboarding').classList.remove('open');$('du-portal').classList.add('open');syncPortalIdentity();loadCredits();openPortalTab('dashboard');history.replaceState(null,'','#portal');}
function closePortal(){$('du-portal').classList.remove('open');$('du-profile-panel').classList.remove('open');}
function navigate(page){const a=document.querySelector(`[data-page="${page}"]`);if(a)a.click();else location.hash='#'+page;}
async function loadCredits(){if(!client||!currentUser)return;const {data}=await client.from('arch_coach_credit_accounts').select('plan_code,monthly_credits_remaining,purchased_credits_remaining,unlimited_access').eq('user_id',currentUser.id).maybeSingle();if(!data)return;$('du-plan-status').textContent=data.unlimited_access?'Unlimited Arch Coach':(data.plan_code||'Explore');$('du-credit-copy').textContent=data.unlimited_access?'Unlimited Arch Coach access enabled for this account.':`${(data.monthly_credits_remaining||0)+(data.purchased_credits_remaining||0)} credits available.`;}
function openProfileEditor(){closePortal();onboarding(true);showStep(0);$('du-skip').textContent='Close';$('du-skip').onclick=()=>{$('du-onboarding').classList.remove('open');openPortal()};}
async function signOut(){if(client)await client.auth.signOut();currentUser=null;currentProfile=null;document.documentElement.classList.remove('du-authenticated');closePortal();location.hash='#home';location.reload();}
async function afterAuth(user,force=true){if(!user||user.is_anonymous)return;const now=Date.now();if(now-lastAuthRun<500)return;lastAuthRun=now;currentUser=user;try{currentProfile=await Promise.race([loadProfile(user),new Promise(r=>setTimeout(()=>r(null),1800))]);if(!currentProfile&&client){client.from('profiles').upsert({id:user.id,display_name:user.user_metadata?.display_name||user.email?.split('@')[0]||'DrawUp Member'},{onConflict:'id'}).then(()=>{}).catch(()=>{});}}catch(e){console.warn('Profile load did not block portal:',e)}decorateSignedIn();if(force)tunnel();else openPortal();}
function decorateSignedIn(){document.documentElement.classList.add('du-authenticated');document.querySelectorAll('.join-preseason').forEach(x=>{x.style.display='none';x.setAttribute('aria-hidden','true')});const sign=document.getElementById('drawup-signin');if(sign){sign.textContent='Portal';sign.onclick=e=>{e.preventDefault();openPortal()}}if(!document.querySelector('.mobile-bottom-nav [data-du-profile]')){const nav=document.querySelector('.mobile-bottom-nav');if(nav){const a=document.createElement('a');a.href='#portal';a.dataset.duProfile='1';a.innerHTML='<span class="m-icon">●</span><span>Profile</span>';a.onclick=e=>{e.preventDefault();openPortal()};nav.appendChild(a)}}}
function gatePricing(){document.querySelectorAll('#page-pricing .price-card').forEach(card=>{const name=card.querySelector('h3')?.textContent?.trim();if(!name||name==='Explore'||name==='Firm Free'||card.querySelector('.du-purchase'))return;const b=document.createElement('button');b.className='btn btn-primary du-purchase';b.type='button';b.textContent='Choose '+name;b.onclick=async()=>{pendingPlan=name;const {data}=await client.auth.getSession();const u=data.session?.user;if(!u||u.is_anonymous){window.DrawUpV131PendingPlan=name;document.getElementById('drawup-signin')?.click();const st=document.getElementById('auth-status');if(st)st.textContent='Sign in or create an account before purchasing '+name+'.';}else{await afterAuth(u,false);openPortal();$('du-plan-status').textContent='Selected: '+name+' · checkout requires signed-in account';}};card.appendChild(b);const p=document.createElement('div');p.className='du-auth-required';p.textContent='DrawUp account required to purchase.';card.appendChild(p)});}
window.DrawUpPortalAfterAuth=(user)=>afterAuth(user,true);
async function init(){mount();client=await waitClient();if(!client)return;gatePricing();client.auth.onAuthStateChange((event,session)=>{if((event==='SIGNED_IN'||event==='INITIAL_SESSION')&&session?.user&&!session.user.is_anonymous){setTimeout(()=>afterAuth(session.user,event==='SIGNED_IN'),0)}});const {data}=await client.auth.getSession();if(data.session?.user&&!data.session.user.is_anonymous){currentUser=data.session.user;currentProfile=await loadProfile(currentUser);decorateSignedIn();openPortal();}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();

/* V13.9 functional portal workspaces */
function duYearsExperience(career){const now=new Date();let months=0;(career||[]).forEach(r=>{if(!r.start_date)return;const s=new Date(r.start_date),e=r.end_date?new Date(r.end_date):now;if(e>s)months+=(e.getFullYear()-s.getFullYear())*12+(e.getMonth()-s.getMonth())});return months/12}
async function duProfileData(){let edu=[],career=[],saved=[],connections=[];try{const [e,c,s,n]=await Promise.all([client.from('profile_education').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}),client.from('career_timeline').select('*').eq('user_id',currentUser.id).order('start_date',{ascending:false}),client.from('saved_items').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}).limit(50),client.from('connections').select('*').or(`requester_id.eq.${currentUser.id},addressee_id.eq.${currentUser.id}`).limit(50)]);edu=e.data||[];career=c.data||[];saved=s.data||[];connections=n.data||[]}catch(e){}return{edu,career,saved,connections}}
function duList(title,items,empty){return `<article class="du-glass du-wide"><span class="du-kicker">${esc(title)}</span>${items.length?items.join(''):`<p>${esc(empty)}</p>`}</article>`}
async function duRenderProfilePane(name,host,data){host.querySelectorAll('.du-subtabs button').forEach(b=>b.classList.toggle('active',b.dataset.profilePane===name));const p=host.querySelector('#du-profile-pane');if(!p)return;if(name==='overview'){p.innerHTML=`<div class="du-profile-grid"><article class="du-glass du-edit-card" data-inline-edit="affiliation"><span class="du-kicker">CURRENT AFFILIATION · CLICK TO EDIT</span><h2>${esc(currentProfile?.primary_affiliation_name||'Add affiliation')}</h2><p>Your current affiliation stays separate from your history.</p></article><article class="du-glass du-edit-card" data-profile-pane-jump="experience"><span class="du-kicker">WORK EXPERIENCE · CLICK TO EDIT</span><h2>${data.career.length} roles</h2><p>${duYearsExperience(data.career).toFixed(1)} years recorded.</p></article><article class="du-glass du-edit-card" data-profile-pane-jump="education"><span class="du-kicker">EDUCATION + TRADE · CLICK TO EDIT</span><h2>${data.edu.length} records</h2><p>Universities, colleges, trade schools and apprenticeships.</p></article><article class="du-glass du-edit-card" data-inline-edit="bio"><span class="du-kicker">ABOUT · CLICK TO EDIT</span><p>${esc(currentProfile?.bio||'Add a bio to tell the DrawUp community about your work and interests.')}</p></article></div>`;p.querySelectorAll('[data-profile-pane-jump]').forEach(x=>x.onclick=()=>duRenderProfilePane(x.dataset.profilePaneJump,host,data));p.querySelectorAll('[data-inline-edit]').forEach(x=>x.onclick=async()=>{const k=x.dataset.inlineEdit;if(k==='bio'){const v=prompt('About / bio',currentProfile?.bio||'');if(v===null)return;await saveProfile({bio:v.trim()||null})}else{const v=prompt('Current firm / affiliation',currentProfile?.primary_affiliation_name||'');if(v===null)return;await saveProfile({primary_affiliation_name:v.trim()||null,primary_affiliation_type:v.trim()?'firm':null})}const fresh=await duProfileData();duRenderProfilePane('overview',host,fresh)});return}
if(name==='experience'){p.innerHTML=duList('WORK EXPERIENCE',data.career.map(x=>`<div class="du-row"><div><b>${esc(x.role||'Role')}</b><span>${esc(x.organization||'')}</span></div><small>${esc(x.start_date||'')} ${x.end_date?'— '+esc(x.end_date):'— Present'}</small></div>`),'No work history yet. Use Edit profile to add experience.');return}
if(name==='education'){p.innerHTML=duList('EDUCATION + TRADE',data.edu.map(x=>`<div class="du-row"><div><b>${esc(x.institution_name)}</b><span>${esc([x.program,x.degree_or_certificate].filter(Boolean).join(' · '))}</span></div><small>${esc(x.status||'')}</small></div>`),'No education or trade records yet.');return}
if(name==='credentials'){const a=currentProfile?.credentials||[];p.innerHTML=duList('CREDENTIALS',a.map(x=>`<div class="du-row"><b>${esc(x)}</b><span class="du-live-pill">PROFILE CREDENTIAL</span></div>`),'Add licenses, AIA/NCARB/PE/LEED and certifications from Edit profile.');return}
if(name==='connections'){p.innerHTML=duList('CONNECTIONS',data.connections.map(()=>`<div class="du-row"><b>DrawUp connection</b><span>Connected through your AEC network</span></div>`),'No connections yet. Open Connect to grow your network.');return}
if(name==='saved'){p.innerHTML=duList('SAVED',data.saved.map(x=>`<div class="du-row"><div><b>${esc(x.label||x.entity_key)}</b><span>${esc(x.entity_type)}</span></div></div>`),'Nothing saved yet.');return}
if(name==='projects'){p.innerHTML=`<article class="du-glass du-wide"><span class="du-kicker">PROJECTS</span><h2>Your project portfolio</h2><p>Project records associated with your account will appear here.</p><button class="du-btn primary" data-portal-tab="projects">Open Projects →</button></article>`}}
async function renderProfile(w){const n=currentProfile?.display_name||'DrawUp Member',data=await duProfileData();w.innerHTML=`<div class="du-profile-cover"><div class="du-profile-orb">${avatarHTML()}</div><div><span class="du-kicker">DRAWUP PROFILE</span><h1>${esc(n)}</h1><p>${esc([currentProfile?.title,currentProfile?.primary_affiliation_name,currentProfile?.current_location].filter(Boolean).join(' · '))}</p><div class="du-badges">${(currentProfile?.disciplines||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><button class="du-btn primary" id="du-edit-profile">Edit profile</button></div><div class="du-subtabs">${[['overview','Overview'],['projects','Projects'],['experience','Experience'],['education','Education + Trade'],['credentials','Credentials'],['connections','Connections'],['saved','Saved']].map((x,i)=>`<button data-profile-pane="${x[0]}" class="${i?'':'active'}">${x[1]}</button>`).join('')}</div><div id="du-profile-pane"></div>`;$('du-edit-profile').onclick=openProfileEditor;w.querySelectorAll('[data-profile-pane]').forEach(b=>b.onclick=()=>duRenderProfilePane(b.dataset.profilePane,w,data));duRenderProfilePane('overview',w,data)}
const DU_CATS=['Wall Sections','Exterior Walls','Roofs','Foundations','Slabs','Doors','Windows','Storefront / Curtain Wall','Stairs','Railings','Restrooms / ADA','Millwork','Interiors','Ceilings','Structural','MEP Coordination','Site','Fire / Life Safety','Typical Details','Custom'];
async function duGetDetails(scope){try{let q=client.from('details').select('*,detail_assets(*)').order('created_at',{ascending:false}).limit(100);if(scope==='firm')q=q.eq('firm_name',currentProfile?.primary_affiliation_name||'__none__').in('visibility',['firm','drawup']);else q=q.eq('status','published').eq('visibility','drawup');const {data,error}=await q;if(error)throw error;return data||[]}catch(e){return[]}}
function duDetailCard(d){const assets=d.detail_assets||[];const types=[...new Set(assets.map(a=>(a.file_ext||'FILE').toUpperCase()))];return `<article class="du-detail-card"><div class="du-detail-thumb">${d.preview_url?`<img src="${esc(d.preview_url)}" alt="">`:'<b>DETAIL</b>'}</div><div class="du-detail-body"><span class="du-kicker">${esc(d.category||'Detail')}</span><h3>${esc(d.title||'Untitled detail')}</h3><p>${esc(d.description||'Professional detail resource')}</p><div class="du-filetypes">${types.map(x=>`<span>${esc(x)}</span>`).join('')||'<span>RESOURCE</span>'}</div>${assets.map(a=>`<a class="du-download" href="${esc(a.public_url||'#')}" target="_blank" rel="noopener">${esc((a.file_ext||'file').toUpperCase())} ${a.public_url?'View / download':'stored'}</a>`).join('')}</div></article>`}
async function duUploadDetail(scope='drawup'){const data=await duProfileData(),yrs=duYearsExperience(data.career),licensed=(currentProfile?.credentials||[]).length>0||currentProfile?.profile_verified;const canCommunity=yrs>=5||licensed;if(scope==='drawup'&&!canCommunity){alert('Publishing to DrawUp Details requires 5+ years of recorded professional experience or a verified professional credential. You can still upload to your firm library.');return}const title=prompt('Detail title');if(!title)return;const category=prompt('Category:\n'+DU_CATS.join(', '),'Typical Details')||'Custom';const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='.pdf,.jpg,.jpeg,.png,.dwg,.dxf,.rvt,.rfa,.doc,.docx,.xls,.xlsx,.zip';input.onchange=async()=>{if(!input.files?.length)return;const firm=currentProfile?.primary_affiliation_name||null;const visibility=scope==='both'?'drawup':scope;const {data:d,error}=await client.from('details').insert({owner_id:currentUser.id,title,category,visibility:visibility==='firm'?'firm':'drawup',firm_name:firm,status:visibility==='firm'?'published':'submitted'}).select().single();if(error){alert('Detail database is not installed yet. Run the V13.9 Supabase SQL included with this release.');return}for(const f of input.files){const ext=(f.name.split('.').pop()||'file').toLowerCase(),path=`${currentUser.id}/${d.id}/${Date.now()}-${f.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await client.storage.from('drawup-files').upload(path,f,{upsert:false});if(up.error)continue;const {data:url}=client.storage.from('drawup-files').getPublicUrl(path);await client.from('detail_assets').insert({detail_id:d.id,owner_id:currentUser.id,file_name:f.name,file_ext:ext,storage_path:path,public_url:url.publicUrl,file_size:f.size})}alert(visibility==='firm'?'Added to your firm library.':'Submitted to DrawUp Details.');openPortalTab(scope==='firm'?'firm':'details')};input.click()}
async function renderDetails(w){const list=await duGetDetails('drawup');w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">DRAWUP DETAILS</span><h1>Detail Library</h1><p>Browse real drawing details and their available PDF, image, CAD and BIM files.</p></div><div class="du-head-actions"><button class="du-btn ghost" id="du-upload-firm">Upload to firm</button><button class="du-btn primary" id="du-upload-community">Upload detail</button></div></div><div class="du-category-strip">${DU_CATS.map(x=>`<button data-cat="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="du-detail-grid" id="du-detail-grid">${list.length?list.map(duDetailCard).join(''):'<article class="du-glass du-wide"><h2>Build the DrawUp detail catalog.</h2><p>Eligible professionals can contribute details. Firm-only uploads remain inside the firm library.</p></article>'}</div>`;$('du-upload-community').onclick=()=>duUploadDetail('drawup');$('du-upload-firm').onclick=()=>duUploadDetail('firm');w.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{w.querySelectorAll('[data-cat]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const filtered=list.filter(d=>d.category===b.dataset.cat);$('du-detail-grid').innerHTML=filtered.length?filtered.map(duDetailCard).join(''):'<article class="du-glass"><h2>No details in this category yet.</h2><p>Be the first eligible contributor.</p></article>'})}
async function duRenderFirmPane(name,w,members){w.querySelectorAll('[data-firm-pane]').forEach(b=>b.classList.toggle('active',b.dataset.firmPane===name));const p=w.querySelector('#du-firm-pane'),firm=currentProfile?.primary_affiliation_name;if(name==='overview')p.innerHTML=`<div class="du-dash-grid"><article class="du-glass du-command"><span class="du-kicker">FIRM PAGE</span><h2>${esc(firm)}</h2><p>Firm identity, projects, people and shared DrawUp activity.</p></article><article class="du-glass"><span class="du-kicker">TEAM</span><h2>${members.length} coworkers on DrawUp</h2><button data-portal-tab="team">Open team →</button></article></div>`;else if(name==='team'){openPortalTab('team');return}else if(name==='library'){const list=await duGetDetails('firm');p.innerHTML=`<div class="du-work-head compact"><div><h2>Firm Library</h2><p>Private details and files for ${esc(firm)}.</p></div><button class="du-btn primary" id="du-firm-upload">Upload files</button></div><div class="du-detail-grid">${list.length?list.map(duDetailCard).join(''):'<article class="du-glass"><h2>Your firm library is ready.</h2><p>Upload PDF, JPG, DWG, DXF, RVT, RFA and supporting files.</p></article>'}</div>`;p.querySelector('#du-firm-upload').onclick=()=>duUploadDetail('firm')}else p.innerHTML=`<article class="du-glass du-wide"><span class="du-kicker">${esc(name.toUpperCase())}</span><h2>${esc(firm)} ${esc(name)}</h2><p>This firm workspace is ready to populate from your DrawUp activity.</p></article>`}
async function renderFirm(w){const firm=currentProfile?.primary_affiliation_name;if(!firm){w.innerHTML=`<div class="du-empty"><h1>Add your firm to unlock your firm page.</h1><button class="du-btn primary" data-portal-tab="profile">Update profile</button></div>`;return}const members=await firmMembers();w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">YOUR FIRM</span><h1>${esc(firm)}</h1><p>Your personal DrawUp account is connected to this firm workspace.</p></div><span class="du-live-pill">${members.length} DRAWUP MEMBERS</span></div><div class="du-subtabs">${[['overview','Overview'],['team','Team'],['projects','Projects'],['pursuits','Pursuits'],['library','Firm Library'],['usage','Usage']].map((x,i)=>`<button data-firm-pane="${x[0]}" class="${i?'':'active'}">${x[1]}</button>`).join('')}</div><div id="du-firm-pane"></div>`;w.querySelectorAll('[data-firm-pane]').forEach(b=>b.onclick=()=>duRenderFirmPane(b.dataset.firmPane,w,members));duRenderFirmPane('overview',w,members)}
const duOpenPortalTabBase=openPortalTab;openPortalTab=async function(tab='dashboard'){document.querySelectorAll('[data-portal-tab]').forEach(x=>x.classList.toggle('active',x.dataset.portalTab===tab));const w=$('du-workspace-content');if(!w)return;w.innerHTML='<div class="du-loading">DRAWING IT UP…</div>';if(tab==='details')return renderDetails(w);return duOpenPortalTabBase(tab)};

})();

/* DrawUp V15 — populated Portal workspaces */
let duEmbeddedPublicPage=null,duEmbeddedHome=null,duEmbeddedNext=null;
function duRestoreEmbedded(){
  if(!duEmbeddedPublicPage||!duEmbeddedHome)return;
  duEmbeddedPublicPage.hidden=true;
  duEmbeddedPublicPage.classList.remove('du-portal-embedded-page');
  if(duEmbeddedNext&&duEmbeddedNext.parentNode===duEmbeddedHome) duEmbeddedHome.insertBefore(duEmbeddedPublicPage,duEmbeddedNext);
  else duEmbeddedHome.appendChild(duEmbeddedPublicPage);
  duEmbeddedPublicPage=null;duEmbeddedHome=null;duEmbeddedNext=null;
}
function duEmbedPublic(w,pageId){
  duRestoreEmbedded();
  const page=document.getElementById(pageId); if(!page){w.innerHTML='<div class="du-empty"><h1>Workspace unavailable.</h1></div>';return;}
  duEmbeddedPublicPage=page;duEmbeddedHome=page.parentNode;duEmbeddedNext=page.nextSibling;
  page.hidden=false;page.classList.add('du-portal-embedded-page');w.innerHTML='';w.appendChild(page);
}
async function duPortalProjects(w){
  let projects=[];
  try{const r=await client.from('projects').select('*').or(`owner_id.eq.${currentUser.id},created_by.eq.${currentUser.id}`).limit(12);projects=r.data||[]}catch(e){try{const r=await client.from('projects').select('*').limit(12);projects=r.data||[]}catch(_){}}
  w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">PROJECTS</span><h1>Your work starts here.</h1><p>Start a project, work with Arch Coach, visualize with Let’s Play, or continue recent work.</p></div></div>
  <div class="du-v15-actions">
    <button class="du-v15-action primary" data-v15-project="new"><span>＋</span><b>Start New</b><small>Create a DrawUp project workspace.</small></button>
    <button class="du-v15-action" data-portal-tab="arch-coach"><span>✦</span><b>Work with Arch Coach</b><small>Ask, analyze and build with project context.</small></button>
    <button class="du-v15-action" data-v15-project="play"><span>◈</span><b>Let’s Play</b><small>Visualize ideas and explore design possibilities.</small></button>
  </div>
  <div class="du-section-title"><div><span class="du-kicker">YOUR PROJECTS</span><h2>${projects.length?'Recent projects':'Ready when you are.'}</h2></div><button class="du-btn ghost" data-portal-tab="search">Search DrawUp</button></div>
  <div class="du-v15-project-grid">${projects.length?projects.map((p,i)=>`<article class="du-glass du-v15-project"><span class="du-kicker">${esc(p.status||'PROJECT')}</span><h3>${esc(p.name||p.title||'Untitled Project')}</h3><p>${esc(p.location||p.project_location||p.description||'DrawUp project')}</p><button data-v15-open-project="${esc(p.id||'')}">Open project →</button></article>`).join(''):`<article class="du-glass du-v15-project-empty"><div class="du-stage-orb"><i></i><b>DU</b></div><h3>Draw it up. See it through.</h3><p>Your active projects will appear here as you create them.</p></article>`}</div>`;
  w.querySelector('[data-v15-project="new"]')?.addEventListener('click',()=>{const n=prompt('Project name');if(!n)return;alert('Project workspace: '+n+'\n\nConnect this action to your production project-creation flow when the projects table fields are finalized.');});
  w.querySelector('[data-v15-project="play"]')?.addEventListener('click',()=>{duRestoreEmbedded();closePortal();navigate('swap')});
}
function duSourceCard(src){const o=Array.isArray(src)?{title:src[0],url:src[1],summary:src[2]}:(src||{});return `<article class="du-glass du-v156-source"><h3>${esc(o.title||o.publisher||'Source')}</h3>${o.summary||o.description||o.snippet?`<p>${esc(o.summary||o.description||o.snippet)}</p>`:''}${o.url?`<a href="${esc(o.url)}" target="_blank" rel="noopener">View source ↗</a>`:''}</article>`}
function duRenderSearchResult(w,r,query){const fields=[['Location',r.location],['Designed by',r.architect],['Engineered by',r.engineers],['Owner / Developer',r.owner],['Opened',r.opened],['Completed',r.completed],['Cost',r.cost],['Capacity',r.capacity]].filter(x=>x[1]);w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">DRAWUP SEARCH</span><h1>${esc(r.title||query)}</h1><p>${esc([r.type,r.location].filter(Boolean).join(' · ')||'DrawUp research')}</p></div><button class="du-btn ghost" data-portal-tab="search">New search</button></div>${r.summary||r.description?`<article class="du-glass du-wide"><h2>Overview</h2><p>${esc(r.summary||r.description)}</p></article>`:''}${r.answer?`<article class="du-glass du-wide"><h2>DrawUp answer</h2><p class="du-answer">${esc(r.answer)}</p></article>`:''}${fields.length?`<div class="du-profile-grid">${fields.map(x=>`<article class="du-glass"><span class="du-kicker">${esc(x[0])}</span><h3>${esc(x[1])}</h3></article>`).join('')}</div>`:''}${Array.isArray(r.items)&&r.items.length?`<div class="du-section-title"><h2>Results</h2></div><div class="du-profile-grid">${r.items.map(x=>`<article class="du-glass"><h3>${esc(x.title||'Result')}</h3>${x.subtitle?`<p>${esc(x.subtitle)}</p>`:''}${x.summary?`<p>${esc(x.summary)}</p>`:''}${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener">Open source ↗</a>`:''}</article>`).join('')}</div>`:''}${Array.isArray(r.sources)&&r.sources.length?`<div class="du-section-title"><h2>Sources</h2></div><div class="du-profile-grid">${r.sources.slice(0,8).map(duSourceCard).join('')}</div>`:''}`}
function duPortalSearchV15(w){
  w.innerHTML=`<div class="du-work-head"><div><span class="du-kicker">DRAWUP SEARCH</span><h1>What are you drawing up?</h1><p>Projects, firms, people, universities, codes, details and resources — without leaving your Portal.</p></div></div><div class="du-search-stage"><div class="du-search-holo"><div class="du-holo-model"><i></i><i></i><i></i><b>DU</b></div></div><form id="du-v15-search" class="du-search-box"><input id="du-v15-q" type="search" placeholder="Search a project, building, firm, person, school, code or detail…" autocomplete="off"><button class="du-btn primary">Search DrawUp →</button></form><div class="du-search-types">${['Projects','Firms','People','Universities','Codes','Details','Resources'].map(x=>`<button type="button" data-v15-type="${x}">${x}</button>`).join('')}</div><div id="du-v156-search-status"></div></div>`;
  const f=w.querySelector('#du-v15-search'),q=w.querySelector('#du-v15-q'),st=w.querySelector('#du-v156-search-status');
  f.onsubmit=async e=>{e.preventDefault();const term=q.value.trim();if(!term)return;st.innerHTML='<div class="du-loading">SEARCHING · FINDING · ASSEMBLING…</div>';try{const res=await fetch('/api/project-research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:term,type:'all'})});const data=await res.json().catch(()=>({}));if(!res.ok||!data?.result)throw new Error(data?.error||'Search unavailable');duRenderSearchResult(w,data.result,term)}catch(err){st.innerHTML=`<article class="du-glass"><h2>Search connection issue</h2><p>${esc(err.message||'Please try again.')}</p></article>`}};
  w.querySelectorAll('[data-v15-type]').forEach(b=>b.onclick=()=>{q.value=b.dataset.v15Type+' ';q.focus()});
}
const duOpenPortalTabPreV15=openPortalTab;
openPortalTab=async function(tab='dashboard'){
  duRestoreEmbedded();
  document.querySelectorAll('[data-portal-tab]').forEach(x=>x.classList.toggle('active',x.dataset.portalTab===tab));
  const w=$('du-workspace-content');if(!w)return;w.innerHTML='<div class="du-loading">DRAWING IT UP…</div>';
  if(tab==='projects')return duPortalProjects(w);
  if(tab==='search')return duPortalSearchV15(w);
  if(tab==='arch-coach')return duEmbedPublic(w,'page-coach');
  if(tab==='check')return duEmbedPublic(w,'page-check');
  if(tab==='details')return duEmbedPublic(w,'page-details');
  if(tab==='discover')return duEmbedPublic(w,'page-discover');
  if(tab==='connect')return duEmbedPublic(w,'page-connect');
  return duOpenPortalTabPreV15(tab);
};

/* DrawUp V15.7 persistence + native Portal Coach patch */
(function(){
async function duToken(){try{return (await client.auth.getSession()).data.session?.access_token||''}catch(e){return''}}
async function duSync(body){const token=await duToken();const r=await fetch('/api/profile-sync',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Could not save profile');return d}
async function duSyncGet(){const token=await duToken();const r=await fetch('/api/profile-sync',{headers:{Authorization:'Bearer '+token}});return r.ok?r.json():{education:[],career:[]}}
// V16: profile history always reads through the authenticated server route so browser RLS/cache cannot hide saved records.
duProfileData=async function(){const d=await duSyncGet();return{edu:Array.isArray(d.education)?d.education:[],career:Array.isArray(d.career)?d.career:[],saved:[],connections:[]}}
function duModal(title,html){let m=document.getElementById('du-inline-modal');if(m)m.remove();document.body.insertAdjacentHTML('beforeend',`<div id="du-inline-modal" class="du-inline-modal"><div class="du-inline-card"><button class="du-inline-x" type="button">×</button><span class="du-kicker">EDIT PROFILE</span><h2>${esc(title)}</h2>${html}</div></div>`);m=document.getElementById('du-inline-modal');m.querySelector('.du-inline-x').onclick=()=>m.remove();return m}
async function duEditBasics(){const m=duModal('Profile',`<div class="du-inline-grid"><label>Display name<input id="die-name" value="${esc(currentProfile?.display_name||'')}"></label><label>Title / role<input id="die-title" value="${esc(currentProfile?.title||'')}"></label><label>Location<input id="die-loc" value="${esc(currentProfile?.current_location||'')}"></label><label>Affiliation<input id="die-aff" value="${esc(currentProfile?.primary_affiliation_name||'')}"></label><label class="wide">Bio<textarea id="die-bio">${esc(currentProfile?.bio||'')}</textarea></label></div><button class="du-btn primary" id="die-save">Save changes</button><span id="die-status"></span>`);m.querySelector('#die-save').onclick=async()=>{const f={display_name:m.querySelector('#die-name').value.trim(),title:m.querySelector('#die-title').value.trim()||null,current_location:m.querySelector('#die-loc').value.trim()||null,primary_affiliation_name:m.querySelector('#die-aff').value.trim()||null,bio:m.querySelector('#die-bio').value.trim()||null};m.querySelector('#die-status').textContent=' Saving…';try{await duSync({profile:f});currentProfile={...currentProfile,...f};m.remove();syncPortalIdentity();openPortalTab('profile')}catch(e){m.querySelector('#die-status').textContent=' '+e.message}}}
async function duEditEducation(){const m=duModal('Education + Trade',`<div class="du-inline-grid"><label>School / program<input id="die-school"></label><label>Type<select id="die-etype"><option value="university">University / college</option><option value="community_college">Community college</option><option value="trade">Trade / technical school</option><option value="apprenticeship">Apprenticeship</option><option value="other">Other</option></select></label><label>Program / major<input id="die-program"></label><label>Degree / certificate<input id="die-degree"></label><label>Start year<input id="die-es" type="number"></label><label>Graduation year<input id="die-eg" type="number"></label></div><button class="du-btn primary" id="die-save">Add education</button><span id="die-status"></span>`);m.querySelector('#die-save').onclick=async()=>{const school=m.querySelector('#die-school').value.trim();if(!school)return;const p={institution_name:school,institution_type:m.querySelector('#die-etype').value,program:m.querySelector('#die-program').value.trim()||null,degree_or_certificate:m.querySelector('#die-degree').value.trim()||null,start_year:Number(m.querySelector('#die-es').value)||null,graduation_year:Number(m.querySelector('#die-eg').value)||null,discoverable:true};m.querySelector('#die-status').textContent=' Saving…';try{await duSync({education:p});m.remove();openPortalTab('profile')}catch(e){m.querySelector('#die-status').textContent=' '+e.message}}}
async function duEditCareer(){const m=duModal('Work Experience',`<div class="du-inline-grid"><label>Employer / organization<input id="die-org"></label><label>Role<input id="die-role"></label><label>Location<input id="die-wloc"></label><label>Start date<input id="die-ws" type="date"></label><label>End date<input id="die-we" type="date"></label></div><button class="du-btn primary" id="die-save">Add experience</button><span id="die-status"></span>`);m.querySelector('#die-save').onclick=async()=>{const org=m.querySelector('#die-org').value.trim(),role=m.querySelector('#die-role').value.trim();if(!org||!role)return;const p={organization:org,role,location:m.querySelector('#die-wloc').value.trim()||null,start_date:m.querySelector('#die-ws').value||null,end_date:m.querySelector('#die-we').value||null};m.querySelector('#die-status').textContent=' Saving…';try{await duSync({career:p});m.remove();openPortalTab('profile')}catch(e){m.querySelector('#die-status').textContent=' '+e.message}}}
openProfileEditor=duEditBasics;
// V16: make the entire overview cards reliably editable, regardless of later pane re-renders.
document.addEventListener('click',function(e){const c=e.target.closest('.du-click-edit,[data-profile-pane-jump]');if(!c||!document.getElementById('du-portal')?.classList.contains('open'))return;const pane=c.dataset.editProfile||c.dataset.profilePaneJump;if(pane==='career'||pane==='experience'){e.preventDefault();e.stopImmediatePropagation();duEditCareer()}else if(pane==='education'){e.preventDefault();e.stopImmediatePropagation();duEditEducation()}else if(pane==='basic'){e.preventDefault();e.stopImmediatePropagation();duEditBasics()}},true);
const oldFinish=finishOnboarding;finishOnboarding=async function(){if(!(await checkUsernameAvailability(true)))return;const fields={display_name:$('du-name').value.trim()||currentProfile?.display_name||currentUser?.email?.split('@')[0],username:normalizeUsername($('du-username').value)||null,pronouns:$('du-pronouns').value.trim()||null,current_location:$('du-location').value.trim()||null,title:$('du-title').value.trim()||null,disciplines:[...disciplines],primary_affiliation_type:$('du-aff-type').value||null,primary_affiliation_name:$('du-aff-name').value.trim()||null,onboarding_completed_at:new Date().toISOString(),onboarding_interests:[...interests],avatar_url:pendingAvatar||currentProfile?.avatar_url||null};const body={profile:fields};const edu=$('du-edu-name').value.trim();if(edu)body.education={institution_name:edu,institution_type:$('du-edu-type').value||'other',program:$('du-edu-program').value.trim()||null,degree_or_certificate:$('du-edu-degree').value.trim()||null,start_year:Number($('du-edu-start').value)||null,graduation_year:Number($('du-edu-grad').value)||null,discoverable:true};const org=$('du-work-org').value.trim(),role=$('du-work-role').value.trim();if(org&&role)body.career={organization:org,role,location:$('du-work-location').value.trim()||null,start_date:$('du-work-start').value||null,end_date:$('du-work-end').value||null};$('du-next').disabled=true;$('du-onboard-status').textContent='SAVING YOUR DRAWUP';try{await duSync(body);currentProfile={...currentProfile,...fields};$('du-onboard-status').textContent="LET'S PLAY";setTimeout(()=>{$('du-onboarding').classList.remove('open');openPortal();openPortalTab('profile')},500)}catch(e){$('du-next').disabled=false;$('du-onboard-status').textContent='SAVE FAILED — '+e.message}}
const oldProfile=renderProfile;renderProfile=async function(w){await oldProfile(w);const pane=w.querySelector('#du-profile-pane');const wire=()=>{w.querySelector('#du-edit-profile')&&(w.querySelector('#du-edit-profile').onclick=duEditBasics);w.querySelectorAll('[data-edit-profile]').forEach(x=>x.onclick=()=>({basic:duEditBasics,career:duEditCareer,education:duEditEducation}[x.dataset.editProfile]||duEditBasics)())};wire();const obs=new MutationObserver(wire);if(pane)obs.observe(pane,{childList:true,subtree:true});};
const oldPane=duRenderProfilePane;duRenderProfilePane=function(name,w,data){oldPane(name,w,data);const p=w.querySelector('#du-profile-pane');if(!p)return;if(name==='overview'){const cards=p.querySelectorAll('.du-glass');if(cards[0]){cards[0].dataset.editProfile='basic';cards[0].classList.add('du-click-edit')}if(cards[1]){cards[1].dataset.editProfile='career';cards[1].classList.add('du-click-edit')}if(cards[2]){cards[2].dataset.editProfile='education';cards[2].classList.add('du-click-edit')}}if(name==='experience'){p.insertAdjacentHTML('afterbegin','<button class="du-btn primary" data-edit-profile="career">+ Add work experience</button>')}if(name==='education'){p.insertAdjacentHTML('afterbegin','<button class="du-btn primary" data-edit-profile="education">+ Add education / trade</button>')}p.querySelectorAll('[data-edit-profile]').forEach(x=>x.onclick=()=>({basic:duEditBasics,career:duEditCareer,education:duEditEducation}[x.dataset.editProfile]||duEditBasics)())}
function duCoachKey(){return 'drawup_coach_threads_'+(currentUser?.id||'guest')}
function duThreads(){try{return JSON.parse(localStorage.getItem(duCoachKey())||'[]')}catch(e){return[]}}
function duSaveThreads(v){localStorage.setItem(duCoachKey(),JSON.stringify(v.slice(0,30)))}
function duCoach(w){let threads=duThreads(),active=threads[0]||{id:Date.now().toString(),title:'New play',messages:[]};if(!threads.length){threads=[active];duSaveThreads(threads)};const draw=()=>{w.innerHTML=`<div class="du-coach-shell"><aside class="du-coach-threads"><button class="du-btn primary" id="dc-new">＋ New play</button><div class="du-coach-thread-list">${threads.map(t=>`<button data-thread="${t.id}" class="${t.id===active.id?'active':''}"><b>${esc(t.title||'New play')}</b><small>${t.messages?.length||0} messages</small></button>`).join('')}</div></aside><section class="du-coach-main"><div class="du-work-head"><div><span class="du-kicker">ARCH COACH</span><h1>${esc(active.title||'New play')}</h1><p>Your AEC copilot — research, compare, visualize and keep each question in its own thread.</p></div></div><div class="du-coach-tools"><button data-portal-tab="search">⌕ Search</button><button data-portal-tab="discover">◈ Compare schools</button><button data-portal-tab="connect">∞ Compare firms</button><button id="dc-play">◇ Let’s Play</button><label>＋ Graphic<input id="dc-image" type="file" accept="image/*" hidden></label></div><div id="dc-messages" class="du-coach-messages">${active.messages.length?active.messages.map(m=>`<article class="${m.role}"><span>${m.role==='user'?'YOU':'ARCH COACH'}</span><p>${esc(m.content)}</p>${m.image?`<img src="${m.image}" alt="Attached graphic">`:''}${m.sources?.length?`<div class="du-coach-sources">${m.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title||'Source')} ↗</a>`).join('')}</div>`:''}</article>`).join(''):'<div class="du-coach-empty"><b>What are we drawing up?</b><p>Start a question, research a code, compare a firm or school, or pull in a graphic.</p></div>'}</div><div id="dc-preview"></div><form id="dc-form" class="du-coach-compose"><textarea id="dc-input" rows="3" placeholder="Ask Arch Coach…"></textarea><button class="du-btn primary">Send</button></form><div id="dc-status" class="du-muted"></div></section></div>`;bind()};let pendingImage='';const bind=()=>{w.querySelector('#dc-new').onclick=()=>{active={id:Date.now().toString(),title:'New play',messages:[]};threads.unshift(active);duSaveThreads(threads);draw()};w.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>{active=threads.find(t=>t.id===b.dataset.thread)||active;draw()});w.querySelector('#dc-play').onclick=()=>openPortalTab('projects');const fi=w.querySelector('#dc-image');fi.onchange=()=>{const f=fi.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{pendingImage=String(r.result);w.querySelector('#dc-preview').innerHTML=`<div class="du-coach-preview"><img src="${pendingImage}"><span>${esc(f.name)}</span></div>`};r.readAsDataURL(f)};w.querySelector('#dc-form').onsubmit=async e=>{e.preventDefault();const inp=w.querySelector('#dc-input'),text=inp.value.trim();if(!text&&!pendingImage)return;const user={role:'user',content:text||'Review this graphic.',image:pendingImage||undefined};active.messages.push(user);if(active.title==='New play')active.title=(text||'Graphic review').slice(0,42);inp.value='';const img=pendingImage;pendingImage='';duSaveThreads(threads);draw();const st=w.querySelector('#dc-status');st.textContent='Arch Coach is drawing it up…';try{const history=active.messages.map(x=>({role:x.role,content:x.content}));const r=await fetch('/api/arch-coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:user.content,history,image:img,location:currentProfile?.current_location||''})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Connection issue');active.messages.push({role:'assistant',content:d.answer,sources:d.sources||[]});duSaveThreads(threads);draw()}catch(err){st.textContent=err.message||'Connection issue'}}};draw()}
window.duCoachNative=duCoach;
const prevOpen=openPortalTab;openPortalTab=async function(tab='dashboard'){if(tab==='arch-coach'){duRestoreEmbedded?.();document.querySelectorAll('[data-portal-tab]').forEach(x=>x.classList.toggle('active',x.dataset.portalTab===tab));const w=$('du-workspace-content');duCoach(w);return}return prevOpen(tab)};
})();

/* DrawUp V15.9 containment + refresh-safe profile reload + Coach shot clock */
(function(){
  // While authenticated inside Portal, navigation stays in Portal unless Sign out is chosen.
  document.addEventListener('click',function(e){
    const portal=document.getElementById('du-portal');
    if(!portal?.classList.contains('open')) return;
    const el=e.target.closest('[data-page]'); if(!el) return;
    const map={discover:'discover',connect:'connect',details:'details',coach:'arch-coach',check:'check',swap:'projects',firms:'firm',profile:'profile',pricing:'account'};
    const tab=map[el.dataset.page];
    if(tab){e.preventDefault();e.stopImmediatePropagation();openPortalTab(tab)}
  },true);
  // Refresh profile from Supabase whenever the tab opens so saved DB data wins over stale browser state.
  const prior=openPortalTab;
  openPortalTab=async function(tab='dashboard'){
    if(currentUser && (tab==='profile'||tab==='dashboard')){
      try{const fresh=await loadProfile(currentUser);if(fresh)currentProfile=fresh}catch(_e){}
    }
    return prior(tab);
  };
  // Native Arch Coach: visible 10-second shot clock; overtime continues instead of failing the request.
  const priorCoach=duCoach;
  duCoach=function(w){
    priorCoach(w);
    const form=w.querySelector('#dc-form'); if(!form||form.dataset.shotclock)return;
    form.dataset.shotclock='1';
    form.addEventListener('submit',()=>{
      let left=10; const tick=()=>{
        const st=w.querySelector('#dc-status'); if(!st)return;
        if(left>0){st.textContent='ARCH COACH · SHOT CLOCK '+left+'s';left--;setTimeout(tick,1000)}
        else if(st.textContent.startsWith('ARCH COACH · SHOT CLOCK')) st.textContent='ARCH COACH · OVERTIME — finishing your answer…';
      }; setTimeout(tick,50);
    },true);
  };
})();


